            // Cannot fit next item; penalize this bin slightly to keep it for smaller items
            score += 15.0;
        } else {
            // Can fit next item; reward this bin
            score -= 10.0;
        }
    }

    // 3. Global Efficiency: If we have many open bins, prioritize closing them (Best Fit)
    // If we have few open bins, prioritize creating balanced future capacity
    let progress = step_index as f64 / total_items as f64;
    let global_pressure = (open_bins_count as f64) * (1.0 - progress);
    score += global_pressure * 0.5;

    // 4. New Bin Thresholding:
    // If this is a new bin (bin_residual == bin_capacity), set a threshold cost.
    // We only open a new bin if the current 'best' fit is extremely poor (post_residual very small).
    if bin_residual == bin_capacity {
        // High base cost to open a new bin; only lower it if the stream is early
        // or if we have no other options.
        score = 45.0 + (progress * 20.0);
        if fitting_bins_count == 0 {
            score = 0.0; // Forced to open
        }
    } else {
        // Encourage using existing bins that have residuals close to the mean
        let deviation = (bin_residual as f64 - mean_residual).abs();
        score += deviation * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Penalize small residual slices that are too small for common items (10-30 range)
    // but reward perfect fits (residual 0) heavily.
    let fit_penalty = if post_res == 0.0 {
        -50.0
    } else if post_res < 15.0 {
        40.0 / (post_res + 0.1)
    } else {
        post_res * 0.1
    };

    // Lookahead logic: If the next item can fit in the current post_residual, 
    // prioritize this bin to keep the packing tight.
    let lookahead_bonus = if next_item_size > 0 && post_res >= next_item_size as f64 {
        -30.0 * (1.0 - progress)
    } else {
        0.0
    };

    // Global state management: 
    // If few bins fit the current item, avoid opening a new bin unless the 
    // current bin results in a very poor residual.
    let scarcity_penalty = if fitting_bins_count <= 1 && bin_residual != bin_capacity {
        -100.0
    } else {
        0.0
    };

    // Non-linear coupling: 
    // As the stream progresses, prioritize filling existing bins (mean_residual)
    // more aggressively to close them out.
    let completion_pressure = (mean_residual - post_res) * progress;

    let score = fit_penalty + lookahead_bonus + scarcity_penalty + completion_pressure;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize small residuals that are likely to become stranded (dead space)
    // We use a parabolic penalty centered near 5-15, which is generally hard to fill.
    let dead_space_penalty = if post > 0.0 && post < 20.0 {
        (20.0 - post).powi(2) * 0.5
    } else {
        0.0
    };

    // Reward bins that align with the next item size (lookahead)
    // If the next item fits perfectly, we prioritize this bin.
    let lookahead_reward = if next_item_size > 0 && (post as u32) >= next_item_size {
        let fit_tightness = (post - next_item_size as f64) / bin_capacity as f64;
        -15.0 * (1.0 - fit_tightness)
    } else {
        0.0
    };

    // Dynamic preference: early in the stream, favor Best Fit (low post_residual).
    // Late in the stream, avoid opening new bins by favoring bins that keep 
    // the mean_residual high enough to accommodate remaining items.
    let progress_weight = 10.0 * progress;
    let balance_factor = (mean_residual - post) * progress_weight;

    // Favor bins that are already open (fitting_bins_count > 0) over new bins
    // unless the fit is extremely poor.
    let new_bin_penalty = if bin_residual == bin_capacity && open_bins_count > 0 {
        40.0 * (1.0 - progress * 0.5)
    } else {
        0.0
    };

    // Combine: Minimize score.
    // Base is post_residual (Best Fit).
    // Add penalties for dead space.
    // Subtract rewards for lookahead and bin utilization efficiency.
    post + dead_space_penalty + lookahead_reward + balance_factor + new_bin_penalty
}
